    h, w = len(grid), len(grid[0])
    divider_rows = {r for r, row in enumerate(grid) if len(set(row)) == 1}
    divider_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    def segments(length, dividers):
        out = []
        start = 0
        for i in range(length):
            if i in dividers:
                if start < i:
                    out.append((start, i))
                start = i + 1
        if start < length:
            out.append((start, length))
        return out

    row_segments = segments(h, divider_rows)
    col_segments = segments(w, divider_cols)
    panels = [(r0, r1, c0, c1) for r0, r1 in row_segments for c0, c1 in col_segments]
    if len(panels) <= 1:
        return [row[:] for row in grid]

    def panel_data(panel):
        r0, r1, c0, c1 = panel
        return [row[c0:c1] for row in grid[r0:r1]]

    # The non-uniform panel is the motif; uniform panels are its empty destinations.
    source = max(panels, key=lambda p: len({v for row in panel_data(p) for v in row}))
    motif = panel_data(source)
    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in panels:
        if (r1 - r0, c1 - c0) == (len(motif), len(motif[0])):
            for dr in range(r1 - r0):
                for dc in range(c1 - c0):
                    out[r0 + dr][c0 + dc] = motif[dr][dc]
    return out


